 cerr << "Erro ao abrir o arquivo!" << endl; 
 return 1; 
} 
string linha; 
while (getline(arquivo, linha)) { 
 cout << linha << endl; 
} 

arquivo.close(); 

A função close() serve para fechar um arquivo depois de usá-lo, garante que tudo seja salvo no arquivo antes de fechá-lo.

