 a) 9 8 3 6 2 1
 b) 1 3 6 9 8 2
 c) 1 2 6 3 8 9
 d) 1 2 6 8 9 3

Pretende-se implementar um programa em C++ que permita:


 a) Criar uma árvore binária de pesquisa (BST) com os seguintes valores: {28, 14, 37, 6, 19, 42, 3, 25, 31, 48}. Deverá ser usada uma função inserirNodo, e a raiz deve ser corretamente inicializado com NULL.
 b) Implementar as seguintes funções:
 bool existe(nodo* raiz, int valor) - devolve verdadeiro se o valor existir na árvore, e falso caso contrário (pesquisa recursiva). void imprimirFolhas(nodo* raiz) - imprime no ecrã os valores de todos os nós folha da árvore (nós sem filhos). int somaValores(nodo* raiz) - calcula recursivamente e retorna a soma total dos valores de todos os nós da árvore. Nota: A estrutura da árvore deve usar a seguinte definição:
 struct nodo {
 int dados;
 nodo* esq;
 nodo* dir;
};

student_answer:
#include 
using namespace std;

struct nodo {
 int dados;
 nodo* esq;
 nodo* dir;
};

void inserirNodo(nodo*& raiz, int valor) {
 if (raiz == NULL) {
 raiz = new nodo;
 raiz->dados = valor;
 raiz->esq = NULL;
 raiz->dir = NULL;
 }
 else if (valor > raiz->dados) {
 inserirNodo(raiz->esq, valor); 
 }
 else {
 inserirNodo(raiz->dir, valor); 
 }
}

bool existe(nodo* raiz, int valor) {
 if (raiz == NULL)
 return false;
 if (raiz->dados == valor)
 return true;
 else if (valor > raiz->dados) {
 return existe(raiz->esq, valor); 
 }
 else {
 return existe(raiz->dir, valor); 
 }
}

void imprimirFolhas(nodo* raiz) {
 if (raiz == NULL)
 return;
 if (raiz->esq == NULL && raiz->dir == NULL)
 cout dados esq);
 imprimirFolhas(raiz->dir);
}

int somaValores(nodo* raiz) {
 if (raiz == NULL)
 return 0;
 return raiz->dados + somaValores(raiz->esq) + somaValores(raiz->dir);
}

int main() {
 nodo* raiz = NULL;

 int valores[] = {28, 14, 37, 6, 19, 42, 3, 25, 31, 48};
 for (int i = 0; i < 10; i++) {
 inserirNodo(raiz, valores[i]);
 }

 int valorProcurado = 19;
 if (existe(raiz, valorProcurado)) {
 cout << "O valor " << valorProcurado << " existe na arvore." << endl;
 } else {
 cout << "O valor " << valorProcurado << " nao existe na arvore." << endl;
 }

 cout << "Nos folha da arvore: ";
 imprimirFolhas(raiz);
 cout << endl;

 cout << "A soma dos valores na arvore e: " << somaValores(raiz) << endl;

 return 0;
}

